cpp.setup:
auto* control = new fluent::collections::FileListView(%PARENT%);
control->setAnimationEnabled(false);
control->setHeaderText(QStringLiteral("Attachments"));
auto* model = new QStandardItemModel(control);
const struct {
    QString name;
    QString detail;
    fluent::collections::FileListView::Status status;
    double progress;
    bool retryable;
} files[] = {
    {QStringLiteral("brand-guidelines.pdf"), QStringLiteral("2.4 MB · Ready to use"), fluent::collections::FileListView::Ready, 1.0, false},
    {QStringLiteral("product-shot.png"), QStringLiteral("3.6 / 5.8 MB · Uploading"), fluent::collections::FileListView::Uploading, 0.62, false},
    {QStringLiteral("release-notes.pdf"), QStringLiteral("Connection lost · Retry when ready"), fluent::collections::FileListView::Rejected, 0.0, true},
};
for (const auto& entry : files) {
    auto* item = new QStandardItem(entry.name);
    item->setData(entry.detail, fluent::collections::FileListView::MetadataRole);
    item->setData(static_cast<int>(entry.status), fluent::collections::FileListView::StatusRole);
    item->setData(entry.progress, fluent::collections::FileListView::ProgressRole);
    item->setData(entry.retryable, fluent::collections::FileListView::RetryableRole);
    model->appendRow(item);
}
control->setModel(model);
control->setCurrentIndex(model->index(0, 0));
